const crypto = require('crypto');

const cfg = $input.first().json;
const conn = cfg.connectionString;
if (!conn) {
  throw new Error('No connection string provided in Fleet Config.');
}

const parts = {};
conn.split(';').forEach(segment => {
  const idx = segment.indexOf('=');
  if (idx > -1) {
    parts[segment.substring(0, idx).trim()] = segment.substring(idx + 1).trim();
  }
});

const host = parts.HostName;
const policy = parts.SharedAccessKeyName;
const key = parts.SharedAccessKey;

if (!host || !policy || !key) {
  throw new Error('Connection string missing HostName, SharedAccessKeyName, or SharedAccessKey.');
}

const resourceUri = encodeURIComponent(host);
const expiry = Math.floor(Date.now() / 1000) + 3600; // valid 1 hour
const toSign = resourceUri + String.fromCharCode(10) + expiry;
const hmac = crypto.createHmac('sha256', Buffer.from(key, 'base64'));
hmac.update(toSign);
const signature = encodeURIComponent(hmac.digest('base64'));

const sasToken = 'SharedAccessSignature sr=' + resourceUri + '&sig=' + signature + '&se=' + expiry + '&skn=' + policy;

return [{ json: {
  sasToken,
  hostName: host,
  staleHours: cfg.staleHours || 24,
  warnBelowPct: cfg.warnBelowPct != null ? cfg.warnBelowPct : 90,
  critBelowPct: cfg.critBelowPct != null ? cfg.critBelowPct : 70,
} }];

// IoT Hub returns a JSON array; the HTTP node splits it into one item per device.
// alwaysOutputData can also emit a single empty {} item when the fleet is empty.
const cfg = $("Generate SAS Token").first().json;
const staleHours = cfg.staleHours || 24;
const devices = $input.all().map((i) => i.json).filter((d) => d && d.deviceId);
const now = Date.now();
const s = { total: devices.length, online: 0, offline: 0, stale: 0, disabled: 0, devices: [] };
for (const d of devices) {
  const last = d.lastActivityTime ? new Date(d.lastActivityTime).getTime() : 0;
  const ageHrs = last ? (now - last) / 3600000 : Infinity;
  const state = d.connectionState === 'Connected' ? 'online' : 'offline';
  if (d.status === 'disabled') s.disabled++;
  else if (state === 'online') s.online++;
  else if (ageHrs > staleHours) s.stale++;
  else s.offline++;
  s.devices.push({ id: d.deviceId, state, status: d.status, ageHrs: Number.isFinite(ageHrs) ? Math.round(ageHrs) : null });
}
const active = s.total - s.disabled;
s.health_pct = active > 0 ? Math.round((s.online / active) * 100) : 100;
const problem = s.offline + s.stale;
const warnBelow = cfg.warnBelowPct != null ? cfg.warnBelowPct : 90;
const critBelow = cfg.critBelowPct != null ? cfg.critBelowPct : 70;
let severity = 'healthy';
if (s.health_pct < critBelow || problem >= Math.max(3, Math.ceil(active * 0.3))) severity = 'critical';
else if (s.health_pct < warnBelow || problem > 0) severity = 'warning';
s.severity = severity;
s.report_date = new Date().toISOString().slice(0, 10);
// Top offenders for the AI narrative
s.top_offenders = s.devices.filter((x) => x.state !== 'online' || x.status === 'disabled').slice(0, 15);
return [{ json: s }];

const cur = $("Classify Fleet").first().json;
const prevItems = $input.all().filter((i) => i.json && Object.keys(i.json).length > 0 && i.json.report_date);
const prev = prevItems.length ? prevItems[0].json : null;
function delta(field) {
  if (!prev || prev[field] == null) return null;
  return cur[field] - prev[field];
}
const deltas = {
  total: delta('total'),
  online: delta('online'),
  offline: delta('offline'),
  stale: delta('stale'),
  disabled: delta('disabled'),
  health_pct: delta('health_pct'),
};
return [{ json: { ...cur, prev: prev || null, deltas } }];

const LF = String.fromCharCode(10);
let ai = ($json && $json.message && $json.message.content) ? $json.message.content : {};
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = { narrative_html: ai }; } }
const d = $("Compute Deltas").first().json;
const dl = d.deltas || {};
function arrow(v) {
  if (v == null) return '';
  if (v > 0) return ' (\u25B2' + v + ')';
  if (v < 0) return ' (\u25BC' + Math.abs(v) + ')';
  return ' (\u25A00)';
}
const risks = Array.isArray(ai.risks) ? ai.risks : [];
const recs = Array.isArray(ai.recommendations) ? ai.recommendations : [];
const badge = { critical: '\uD83D\uDD34 CRITICAL', warning: '\uD83D\uDFE0 WARNING', healthy: '\uD83D\uDFE2 HEALTHY' }[d.severity] || d.severity;
const p = [];
p.push('<h2>IoT Fleet Health \u2014 ' + d.report_date + '</h2>');
p.push('<p><b>Status:</b> ' + badge + ' &nbsp;\u00B7&nbsp; <b>Health:</b> ' + d.health_pct + '%' + arrow(dl.health_pct) + '</p>');
if (ai.headline) p.push('<p><b>' + ai.headline + '</b></p>');
p.push('<h3>Fleet at a glance (vs previous run)</h3>');
p.push('<ul>');
p.push('<li>Total devices: ' + d.total + arrow(dl.total) + '</li>');
p.push('<li>Online: ' + d.online + arrow(dl.online) + '</li>');
p.push('<li>Offline: ' + d.offline + arrow(dl.offline) + '</li>');
p.push('<li>Stale (&gt;24h): ' + d.stale + arrow(dl.stale) + '</li>');
p.push('<li>Disabled: ' + d.disabled + arrow(dl.disabled) + '</li>');
p.push('</ul>');
if (ai.narrative_html) p.push(ai.narrative_html);
if (risks.length) { p.push('<h3>Key risks</h3><ul>'); for (const r of risks) p.push('<li>' + r + '</li>'); p.push('</ul>'); }
if (recs.length) { p.push('<h3>Recommended actions</h3><ul>'); for (const r of recs) p.push('<li>' + r + '</li>'); p.push('</ul>'); }
p.push('<hr><p style="color:#888;font-size:12px">FleetPulse AI \u00B7 automated with n8n</p>');
const html = p.join(LF);
const prefix = d.severity === 'critical' ? '\uD83D\uDD34 URGENT \u2014 ' : d.severity === 'warning' ? '\uD83D\uDFE0 ' : '\u2705 ';
const subject = prefix + 'IoT Fleet Report ' + d.report_date + ' \u2014 ' + d.health_pct + '% healthy';
const slackText = badge + '  |  Fleet health ' + d.health_pct + '%' + arrow(dl.health_pct) + '  |  ' + d.online + ' online / ' + d.offline + ' offline / ' + d.stale + ' stale / ' + d.disabled + ' disabled (of ' + d.total + ')' + (ai.headline ? (LF + ai.headline) : '');
return [{ json: {
  report_date: d.report_date,
  total: d.total, online: d.online, offline: d.offline, stale: d.stale, disabled: d.disabled,
  health_pct: d.health_pct, severity: d.severity,
  subject, html, slackText,
} }];
